    pub position: u64,
    pub delta: i64,
}

pub fn combine_deltas(left: &[StampedDelta], right: &[StampedDelta]) -> Vec<StampedDelta> {
    let mut combined = Vec::with_capacity(left.len() + right.len());
    let mut i = 0;
    let mut j = 0;

    while i < left.len() && j < right.len() {
        if left[i].position < right[j].position {
            combined.push(left[i]);
            i += 1;
        } else if right[j].position < left[i].position {
            combined.push(right[j]);
            j += 1;
        } else {
            combined.push(StampedDelta {
                position: left[i].position,
                delta: left[i].delta + right[j].delta,
            });
            i += 1;
            j += 1;
        }
    }

    combined.extend_from_slice(&left[i..]);
    combined.extend_from_slice(&right[j..]);
    combined
}
