```rust
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Snapshot { /* private fields */ }

impl Snapshot {
    pub fn revision(&self) -> u64;
    pub fn get(&self, key: &str) -> Option<&str>;
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StoreError {
    TransactionAlreadyOpen,
    NoOpenTransaction,
}

pub struct VersionedStore { /* private fields */ }

impl VersionedStore {
    pub fn new() -> Self;
    pub fn begin(&mut self) -> Result<(), StoreError>;
    pub fn put(&mut self, key: String, value: String) -> Result<(), StoreError>;
    pub fn delete(&mut self, key: String) -> Result<(), StoreError>;
    pub fn commit(&mut self) -> Result<u64, StoreError>;
    pub fn rollback(&mut self) -> Result<(), StoreError>;
    pub fn get(&self, key: &str) -> Option<&str>;
    pub fn snapshot(&self) -> Snapshot;
}
```

The store starts empty at revision zero with no transaction. `begin` opens one transaction and fails if one is already open. `put` and `delete` stage changes and fail without an open transaction. Repeated staged operations on a key use the last operation. `get` exposes committed data only.

`commit` applies all staged operations atomically, closes the transaction, increments the revision exactly once, and returns the new revision. `rollback` discards all staged operations and closes the transaction. Both fail when no transaction is open.

A snapshot contains only committed data and its current revision. It must own an independent immutable copy: staging, committing, or rolling back later store changes must not alter an existing snapshot, and reading a snapshot must not provide mutable access to either object.

Use only the Rust standard library and deterministic in-memory state. Do not access the filesystem, network, clock, or randomness. Do not include a `main` function.","reference_code":"use std::collections::BTreeMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Snapshot {
    entries: BTreeMap<String, String>,
    revision: u64,
}

impl Snapshot {
    pub fn revision(&self) -> u64 {
        self.revision
    }

    pub fn get(&self, key: &str) -> Option<&str> {
        self.entries.get(key).map(String::as_str)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StoreError {
    TransactionAlreadyOpen,
    NoOpenTransaction,
}

pub struct VersionedStore {
    committed: BTreeMap<String, String>,
    pending: Option<BTreeMap<String, Option<String>>>,
    revision: u64,
}

impl VersionedStore {
    pub fn new() -> Self {
        Self {
            committed: BTreeMap::new(),
            pending: None,
            revision: 0,
        }
    }

    pub fn begin(&mut self) -> Result<(), StoreError> {
        if self.pending.is_some() {
            return Err(StoreError::TransactionAlreadyOpen);
        }
        self.pending = Some(BTreeMap::new());
        Ok(())
    }

    pub fn put(&mut self, key: String, value: String) -> Result<(), StoreError> {
        let pending = self.pending.as_mut().ok_or(StoreError::NoOpenTransaction)?;
        pending.insert(key, Some(value));
        Ok(())
    }

    pub fn delete(&mut self, key: String) -> Result<(), StoreError> {
        let pending = self.pending.as_mut().ok_or(StoreError::NoOpenTransaction)?;
        pending.insert(key, None);
        Ok(())
    }

    pub fn commit(&mut self) -> Result<u64, StoreError> {
        let pending = self.pending.take().ok_or(StoreError::NoOpenTransaction)?;
        for (key, change) in pending {
            match change {
                Some(value) => {
                    self.committed.insert(key, value);
                }
                None => {
                    self.committed.remove(&key);
                }
            }
        }
        self.revision += 1;
        Ok(self.revision)
    }

    pub fn rollback(&mut self) -> Result<(), StoreError> {
        if self.pending.take().is_none() {
            return Err(StoreError::NoOpenTransaction);
        }
        Ok(())
    }

    pub fn get(&self, key: &str) -> Option<&str> {
        self.committed.get(key).map(String::as_str)
    }

    pub fn snapshot(&self) -> Snapshot {
        Snapshot {
            entries: self.committed.clone(),
            revision: self.revision,
        }
    }
}
