pub enum MachineError {
    AlreadyRunning,
    Offline,
}

pub struct BatchMachine {
    phase: MachinePhase,
    completed_batches: u64,
}

impl BatchMachine {
    pub fn new() -> Self {
        Self {
            phase: MachinePhase::Offline,
            completed_batches: 0,
        }
    }

    pub fn start(&mut self) -> Result<(), MachineError> {
        if self.phase != MachinePhase::Offline {
            return Err(MachineError::AlreadyRunning);
        }
        self.phase = MachinePhase::Intake;
        Ok(())
    }

    pub fn advance(&mut self) -> Result<(), MachineError> {
        self.phase = match self.phase {
            MachinePhase::Offline => return Err(MachineError::Offline),
            MachinePhase::Intake => MachinePhase::Processing,
            MachinePhase::Processing => MachinePhase::Release,
            MachinePhase::Release => {
                self.completed_batches += 1;
                MachinePhase::Intake
            }
        };
        Ok(())
    }

    pub fn stop(&mut self) -> Result<(), MachineError> {
        if self.phase == MachinePhase::Offline {
            return Err(MachineError::Offline);
        }
        self.phase = MachinePhase::Offline;
        Ok(())
    }

    pub fn view(&self) -> MachineView {
        MachineView {
            phase: self.phase,
            completed_batches: self.completed_batches,
        }
    }
}
