ome(value) => {\\n                    self.committed.insert(key, value);\\n                }\\n                None => {\\n                    self.committed.remove(&key);\\n                }\\n            }\\n        }\\n        self.revision += 1;\\n        Ok(self.revision)\\n    }\\n\\n    pub fn rollback(&mut self) -> Result<(), StoreError> {\\n        if self.pending.take().is_none() {\\n            return Err(StoreError::NoOpenTransaction);\\n        }\\n        Ok(())\\n    }\\n\\n    pub fn get(&self, key: &str) -> Option<&str> {\\n        self.committed.get(key).map(String::as_str)\\n    }\\n\\n    pub fn snapshot(&self) -> Snapshot {\\n        let mut entries = self.committed.clone();\\n        if let Some(pending) = &self.pending {\\n            for (key, change) in pending {\\n                match change {\\n                    Some(value) => {\\n                        entries.insert(key.clone(), value.clone());\\n                    }\\n                    None => {\\n                        entries.remove(key);\\n                    }\\n                }\\n            }\\n        }\\n        Snapshot {\\n            entries,\\n            revision: self.revision,\\n        }\\n    }\\n}\\n\",\"known_bad_label\":\"Builds snapshots from committed state plus uncommitted staged changes, violating transaction isolation.\"},{\"id\":\"cap-v2-stateful_workflows-rust-generation-02\",\"problem\":\"Implement a deterministic batch-machine lifecycle as a complete `solution.rs` source file.\\n\\nExpose exactly this public API:\\n\\n```rust\\n#[derive(Clone, Copy, Debug, PartialEq, Eq)]\\npub enum MachinePhase {\\n    Offline,\\n    Intake,\\n    Processing,\\n    Release,\\n}\\n\\n#[derive(Clone, Copy, Debug, PartialEq, Eq)]\\npub struct MachineView {\\n    pub phase: MachinePhase,\\n    pub completed_batches: u64,\\n}\\n\\n#[derive(Clone, Copy, Debug, PartialEq, Eq)]\\npub enum MachineError {\\n    AlreadyRunning,\\n    Offline,\\n}\\n\\npub struct BatchMachine 