{"items":[{"id":"cap-v2-sequence_algorithms-rust-repair-01","test_code":"#[path = "solution.rs"]
mod solution;

use solution::{combine_deltas, StampedDelta};

fn sd(position: u64, delta: i64) -> StampedDelta {
    StampedDelta { position, delta }
}

#[test]
fn combines_sorted_distinct_positions() {
    let left = [sd(1, 10), sd(3, 30), sd(7, 70)];
    let right = [sd(2, 20), sd(3, 4), sd(8, 80)];

    assert_eq!(
        combine_deltas(&left, &right),
        vec![sd(1, 10), sd(2, 20), sd(3, 34), sd(7, 70), sd(8, 80)]
    );
}

