use solution::{StoreError, VersionedStore};

#[test]
fn new_store_is_empty_at_revision_zero() {
    let store = VersionedStore::new();
    let snapshot = store.snapshot();

    assert_eq!(snapshot.revision(), 0);
    assert_eq!(snapshot.get("missing"), None);
    assert_eq!(store.get("missing"), None);
}

#[test]
fn transaction_changes_are_hidden_until_commit() {
    let mut store = VersionedStore::new();
    assert_eq!(store.begin(), Ok(()));
    assert_eq!(store.put("color".into(), "blue".into()), Ok(()));

    assert_eq!(store.get("color"), None);
    let during = store.snapshot();
    assert_eq!(during.revision(), 0);
    assert_eq!(during.get("color"), None);

    assert_eq!(store.commit(), Ok(1));
    assert_eq!(store.get("color"), Some("blue"));
    assert_eq!(store.snapshot().revision(), 1);
}

#[test]
fn repeated_operations_use_the_last_operation_per_key() {
    let mut store = VersionedStore::new();

    store.begin().unwrap();
    store.put("a".into(), "one".into()).unwrap();
    store.put("a".into(), "two".into()).unwrap();
    store.delete("a".into()).unwrap();
    store.put("a".into(), "final".into()).unwrap();
    store.put("b".into(), "temporary".into()).unwrap();
    store.delete("b".into()).unwrap();
    assert_eq!(store.commit(), Ok(1));

    assert_eq!(store.get("a"), Some("final"));
    assert_eq!(store.get("b"), None);
}

#[test]
fn delete_removes_committed_value_only_after_commit() {
    let mut store = VersionedStore::new();
    store.begin().unwrap();
    store.put("key".into(), "value".into()).unwrap();
    store.commit().unwrap();

    store.begin().unwrap();
    store.delete("key".into()).unwrap();
    assert_eq!(store.get("key"), Some("value"));
    assert_eq!(store.commit(), Ok(2));
    assert_eq!(store.get("key"), None);
}

#[test]
fn rollback_discards_staged_changes_and_does_not_increment_revision() {
    let mut store = VersionedStore::new();
    store.begin().unwrap();
    store.put("stable".into(), "old".into()).unwrap();
    assert_eq!(store.commit(), Ok(1));

    store.begin().unwrap();
    store.put("stable".into(), "new".into()).unwrap();
    store.put("extra".into(), "value".into()).unwrap();
    assert_eq!(store.rollback(), Ok(()));

    assert_eq!(store.get("stable"), Some("old"));
    assert_eq!(store.get("extra"), None);
    assert_eq!(store.snapshot().revision(), 1);

    assert_eq!(store.begin(), Ok(()));
    assert_eq!(store.commit(), Ok(2));
}

#[test]
fn invalid_operations_return_errors_without_changing_state() {
    let mut store = VersionedStore::new();

    assert_eq!(
        store.put("x".into(), "value".into()),
        Err(StoreError::NoOpenTransaction)
    );
    assert_eq!(
        store.delete("x".into()),
        Err(StoreError::NoOpenTransaction)
    );
    assert_eq!(store.commit(), Err(StoreError::NoOpenTransaction));
    assert_eq!(store.rollback(), Err(StoreError::NoOpenTransaction));
    assert_eq!(store.snapshot().revision(), 0);

    assert_eq!(store.begin(), Ok(()));
    store.put("x".into(), "staged".into()).unwrap();
    assert_eq!(store.begin(), Err(StoreError::TransactionAlreadyOpen));
    assert_eq!(store.get("x"), None);
    assert_eq!(store.commit(), Ok(1));
    assert_eq!(store.get("x"), Some("staged"));
}

#[test]
fn every_successful_commit_increments_once_including_empty_commit() {
    let mut store = VersionedStore::new();

