    store.begin().unwrap();
    store.put("a".into(), "1".into()).unwrap();
    store.put("b".into(), "2".into()).unwrap();
    assert_eq!(store.commit(), Ok(2));

    store.begin().unwrap();
    store.delete("absent".into()).unwrap();
    assert_eq!(store.commit(), Ok(3));
    assert_eq!(store.snapshot().revision(), 3);
}

#[test]
fn snapshots_are_independent_immutable_historical_copies() {
    let mut store = VersionedStore::new();
    store.begin().unwrap();
    store.put("name".into(), "first".into()).unwrap();
    store.commit().unwrap();
    let first = store.snapshot();

    store.begin().unwrap();
    store.put("name".into(), "second".into()).unwrap();
    store.put("new".into(), "entry".into()).unwrap();
    assert_eq!(first.revision(), 1);
    assert_eq!(first.get("name"), Some("first"));
    assert_eq!(first.get("new"), None);
    store.commit().unwrap();

    let second = store.snapshot();
    assert_eq!(first.revision(), 1);
    assert_eq!(first.get("name"), Some("first"));
    assert_eq!(first.get("new"), None);
    assert_eq!(second.revision(), 2);
    assert_eq!(second.get("name"), Some("second"));
    assert_eq!(second.get("new"), Some("entry"));

