use solution::{BatchMachine, MachineError, MachinePhase, MachineView};

fn expected(phase: MachinePhase, completed_batches: u64) -> MachineView {
    MachineView {
        phase,
        completed_batches,
    }
}

#[test]
fn new_machine_is_offline_with_no_completed_batches() {
    let machine = BatchMachine::new();
    assert_eq!(machine.view(), expected(MachinePhase::Offline, 0));
}

#[test]
fn start_enters_intake_and_cannot_start_twice() {
    let mut machine = BatchMachine::new();

    assert_eq!(machine.start(), Ok(()));
    assert_eq!(machine.view(), expected(MachinePhase::Intake, 0));
    assert_eq!(machine.start(), Err(MachineError::AlreadyRunning));
    assert_eq!(machine.view(), expected(MachinePhase::Intake, 0));
}

#[test]
fn advance_follows_cycle_and_counts_only_release_to_intake() {
    let mut machine = BatchMachine::new();
    machine.start().unwrap();

    assert_eq!(machine.advance(), Ok(()));
    assert_eq!(machine.view(), expected(MachinePhase::Processing, 0));

    assert_eq!(machine.advance(), Ok(()));
    assert_eq!(machine.view(), expected(MachinePhase::Release, 0));

    assert_eq!(machine.advance(), Ok(()));
    assert_eq!(machine.view(), expected(MachinePhase::Intake, 1));

    machine.advance().unwrap();
    machine.advance().unwrap();
    machine.advance().unwrap();
    assert_eq!(machine.view(), expected(MachinePhase::Intake, 2));
}

#[test]
fn offline_advance_and_stop_fail_without_state_change() {
    let mut machine = BatchMachine::new();

    assert_eq!(machine.advance(), Err(MachineError::Offline));
    assert_eq!(machine.view(), expected(MachinePhase::Offline, 0));
    assert_eq!(machine.stop(), Err(MachineError::Offline));
    assert_eq!(machine.view(), expected(MachinePhase::Offline, 0));
}

#[test]
fn stop_works_from_every_active_phase_and_preserves_count() {
    let mut intake = BatchMachine::new();
    intake.start().unwrap();
    assert_eq!(intake.stop(), Ok(()));
    assert_eq!(intake.view(), expected(MachinePhase::Offline, 0));

    let mut processing = BatchMachine::new();
    processing.start().unwrap();
    processing.advance().unwrap();
    assert_eq!(processing.stop(), Ok(()));
    assert_eq!(processing.view(), expected(MachinePhase::Offline, 0));

    let mut release = BatchMachine::new();
    release.start().unwrap();
    release.advance().unwrap();
    release.advance().unwrap();
    assert_eq!(release.stop(), Ok(()));
    assert_eq!(release.view(), expected(MachinePhase::Offline, 0));

    let mut completed = BatchMachine::new();
    completed.start().unwrap();
    completed.advance().unwrap();
    completed.advance().unwrap();
    completed.advance().unwrap();
    assert_eq!(completed.stop(), Ok(()));
    assert_eq!(completed.view(), expected(MachinePhase::Offline, 1));
}

#[test]
fn restart_always_resumes_at_intake() {
    let mut machine = BatchMachine::new();
    machine.start().unwrap();
    machine.advance().unwrap();
    machine.advance().unwrap();
    machine.advance().unwrap();
    machine.advance().unwrap();
    assert_eq!(machine.view(), expected(MachinePhase::Processing, 1));

    machine.stop().unwrap();
    assert_eq!(machine.start(), Ok(()));
    assert_eq!(machine.view(), expected(MachinePhase::Intake, 1));
}

#[test]
fn previously_returned_views_are_detached_and_stable() {
    let mut machine = BatchMachine::new();
    let offline_view = machine.view();

    machine.start().unwrap();
    let intake_view = machine.view();
    machine.advance().unwrap();
    machine.advance().unwrap();
    machine.advance().unwrap();

    assert_eq!(offline_view, expected(MachinePhase::Offline, 0));
    assert_eq!(intake_view, expected(MachinePhase::Intake, 0));
    assert_eq!(machine.view(), expected(MachinePhase::Intake, 1));

    let copied_view = intake_view;
    assert_eq!(copied_view, intake_view);
