mod solution;

use solution::{DecodeEvent, PacketDecoder};

fn frame(payload: &[u8]) -> Vec<u8> {
    assert!(payload.len() <= u8::MAX as usize);
    let checksum = payload
        .iter()
        .fold(0u8, |sum, byte| sum.wrapping_add(*byte));
    let mut result = Vec::with_capacity(payload.len() + 2);
    result.push(payload.len() as u8);
    result.extend_from_slice(payload);
    result.push(checksum);
    result
}

#[test]
fn decodes_one_complete_packet() {
    let mut decoder = PacketDecoder::new();
    assert_eq!(
        decoder.push(&frame(&[10, 20, 30])),
        vec![DecodeEvent::Packet(vec![10, 20, 30])]
    );
}

#[test]
fn retains_incomplete_frame_across_arbitrary_chunks() {
    let mut decoder = PacketDecoder::new();

    assert_eq!(decoder.push(&[3]), Vec::<DecodeEvent>::new());
    assert_eq!(decoder.push(&[4, 5]), Vec::<DecodeEvent>::new());
    assert_eq!(decoder.push(&[6]), Vec::<DecodeEvent>::new());
    assert_eq!(
        decoder.push(&[15]),
        vec![DecodeEvent::Packet(vec![4, 5, 6])]
    );
}

#[test]
fn processes_multiple_complete_frames_in_stream_order() {
    let mut stream = frame(&[1]);
    stream.extend(frame(&[2, 3]));
    stream.extend(frame(&[]));

    let mut decoder = PacketDecoder::new();
    assert_eq!(
        decoder.push(&stream),
        vec![
            DecodeEvent::Packet(vec![1]),
            DecodeEvent::Packet(vec![2, 3]),
            DecodeEvent::Packet(vec![]),
        ]
    );
}

#[test]
fn malformed_frame_consumes_only_itself_and_following_frame_survives() {
    let malformed = vec![2, 7, 8, 99];
    let valid = frame(&[40, 2]);
    let mut stream = malformed;
    stream.extend(valid);

    let mut decoder = PacketDecoder::new();
    assert_eq!(
        decoder.push(&stream),
        vec![DecodeEvent::Rejected, DecodeEvent::Packet(vec![40, 2])]
    );
}

#[test]
fn rejection_does_not_discard_an_incomplete_following_frame() {
    let mut decoder = PacketDecoder::new();
    let mut first_chunk = vec![1, 9, 8];
    first_chunk.extend_from_slice(&[2, 11]);

    assert_eq!(decoder.push(&first_chunk), vec![DecodeEvent::Rejected]);
    assert_eq!(
        decoder.push(&[12, 23]),
        vec![DecodeEvent::Packet(vec![11, 12])]
    );
}

#[test]
fn incomplete_bad_frame_is_not_rejected_until_checksum_arrives() {
    let mut decoder = PacketDecoder::new();

    assert_eq!(decoder.push(&[2, 1, 2]), Vec::<DecodeEvent>::new());
    assert_eq!(decoder.push(&[]), Vec::<DecodeEvent>::new());
    assert_eq!(decoder.push(&[0]), vec![DecodeEvent::Rejected]);
}

#[test]
fn accepts_zero_length_frames_and_rejects_bad_zero_length_checksum() {
    let mut decoder = PacketDecoder::new();

    assert_eq!(
        decoder.push(&[0, 0, 0, 1]),
        vec![DecodeEvent::Packet(vec![]), DecodeEvent::Rejected]
    );
}

#[test]
fn checksum_uses_wrapping_byte_addition() {
    let mut decoder = PacketDecoder::new();
    let encoded = frame(&[250, 10, 1]);

    assert_eq!(encoded.last(), Some(&5));
    assert_eq!(
        decoder.push(&encoded),
        vec![DecodeEvent::Packet(vec![250, 10, 1])]
    );
}

#[test]
fn supports_maximum_payload_length() {
    let payload: Vec<u8> = (0u16..255).map(|value| value as u8).collect();
    assert_eq!(payload.len(), u8::MAX as usize);
    let encoded = frame(&payload);

    let mut decoder = PacketDecoder::new();
    assert_eq!(
        decoder.push(&encoded),
        vec![DecodeEvent::Packet(payload)]
    );
}

#[test]
fn empty_push_is_stable_and_returned_payload_is_owned() {
    let mut decoder = PacketDecoder::new();
    assert_eq!(decoder.push(&[]), Vec::<DecodeEvent>::new());

    let mut input = frame(&[3, 4]);
    let events = decoder.push(&input);
    input[1] = 99;

    assert_eq!(events, vec![DecodeEvent::Packet(vec![3, 4])]);
    assert_eq!(decoder.push(&[]), Vec::<DecodeEvent>::new());
}"}]}

