#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DecodeEvent {
    Packet(Vec<u8>),
    Rejected,
}

pub struct PacketDecoder {
    buffer: Vec<u8>,
}

impl PacketDecoder {
    pub fn new() -> Self {
        Self { buffer: Vec::new() }
    }

    pub fn push(&mut self, chunk: &[u8]) -> Vec<DecodeEvent> {
        self.buffer.extend_from_slice(chunk);
        let mut events = Vec::new();

        loop {
            let Some(&length_byte) = self.buffer.first() else {
                break;
            };
            let payload_len = length_byte as usize;
            let frame_len = payload_len + 2;
            if self.buffer.len() < frame_len {
                break;
            }

            let checksum = self.buffer[1..1 + payload_len]
                .iter()
                .fold(0u8, |sum, byte| sum.wrapping_add(*byte));
            let encoded_checksum = self.buffer[frame_len - 1];

            if checksum == encoded_checksum {
                events.push(DecodeEvent::Packet(
                    self.buffer[1..1 + payload_len].to_vec(),
                ));
                self.buffer.drain(..frame_len);
            } else {
                events.push(DecodeEvent::Rejected);
                self.buffer.clear();
                break;
            }
        }

        events
    }
