{"type":"item.completed","item":{"id":"item_0","type":"agent_message","text":"{\"items\":[{\"id\":\"cap-v2-stateful_workflows-rust-repair-02\",\"test_code\":\"#[path = \\\"solution.rs\\\"]\\nmod solution;\\n\\nuse solution::{ApplyError, Phase, Workflow};\\n\\n#[test]\\nfn successful_script_reaches_completed_with_name_and_count() {\\n    let mut workflow = Workflow::new();\\n\\n    assert_eq!(workflow.apply_script(\\\"start forge\\\\nadvance\\\\nadvance\\\\nfinish\\\"), Ok(()));\\n    assert_eq!(\\n        workflow.phase(),\\n        &Phase::Completed {\\n            name: \\\"forge\\\".to_owned(),\\n            advances: 2,\\n        }\\n    );\\n}\\n\\n#[test]\\nfn empty_script_is_a_no_op() {\\n    let mut workflow = Workflow::new();\\n\\n    assert_eq!(workflow.apply_script(\\\"\\\"), Ok(()));\\n    assert_eq!(workflow.phase(), &Phase::Idle);\\n}\\n\\n#[test]\\nfn malformed_command_rolls_back_all_preceding_commands() {\\n    let mut workflow = Workflow::new();\\n\\n    assert_eq!(\\n        workflow.apply_script(\\\"start alpha\\\\nadvance\\\\nfinish extra\\\"),\\n        Err(ApplyError::Malformed { command_index: 2 })\\n    );\\n    assert_eq!(workflow.phase(), &Phase::Idle);\\n}\\n\\n#[test]\\nfn invalid_transition_rolls_back_all_preceding_commands() {\\n    let mut workflow = Workflow::new();\\n\\n    assert_eq!(\\n        workflow.apply_script(\\\"start alpha\\\\nadvance\\\\nstart beta\\\"),\\n        Err(ApplyError::InvalidTransition { command_index: 2 })\\n    );\\n    assert_eq!(workflow.phase(), &Phase::Idle);\\n}\\n\\n#[test]\\nfn blank_line_is_malformed_and_reports_its_zero_based_index() {\\n    let mut workflow = Workflow::new();\\n\\n    assert_eq!(\\n        workflow.apply_script(\\\"start alpha\\\\n   \\\\nfinish\\\"),\\n        Err(ApplyError::Malformed { command_index: 1 })\\n    );\\n    assert_eq!(workflow.phase(), &Phase::Idle);\\n}\\n\\n#[test]\\nfn wrong_token_count_on_first_command_is_malformed_without_mutation() {\\n    let mut workflow = Workflow::new();\\n\\n    assert_eq!(\\n        workflow.apply_script(\\\"start\\\"),\\n        Err(ApplyError::Malformed { command_index: 0 })\\n    );\\n    assert_eq!(workflow.phase(), &Phase::Idle);\\n}\\n\\n#[test]\\nfn rollback_restores_exact_preexisting_active_phase() {\\n    let mut workflow = Workflow::new();\\n    workflow.apply_script(\\\"start original\\\\nadvance\\\").unwrap();\\n    let before = workflow.phase().clone();\\n\\n    assert_eq!(\\n        workflow.apply_script(\\\"advance\\\\nadvance extra\\\"),\\n        Err(ApplyError::Malformed { command_index: 1 })\\n    );\\n    assert_eq!(workflow.phase(), &before);\\n}\\n\\n#[test]\\nfn completed_phase_is_unchanged_after_invalid_transition() {\\n    let mut workflow = Workflow::new();\\n    workflow.apply_script(\\\"start done\\\\nadvance\\\\nfinish\\\").unwrap();\\n    let before = workflow.phase().clone();\\n\\n    assert_eq!(\\n        workflow.apply_script(\\\"advance\\\"),\\n        Err(ApplyError::InvalidTransition { command_index: 0 })\\n    );\\n    assert_eq!(workflow.phase(), &before);\\n}\\n\\n#[test]\\nfn whitespace_between_tokens_is_accepted() {\\n    let mut workflow = Workflow::new();\\n\\n    assert_eq!(workflow.apply_script(\\\"  start\\\\talpha  \\\\n advance \\\\n finish \\\"), Ok(()));\\n    assert_eq!(\\n        workflow.phase(),\\n        &Phase::Completed {\\n            name: \\\"alpha\\\".to_owned(),\\n            advances: 1,\\n        }\\n    );\\n}\\n\"},{\"id\":\"cap-v2-string_and_unicode-rust-generation-01\",\"test_code\":\"#[path = \\\"solution.rs\\\"]\\nmod solution;\\n\\nuse solution::folded_inventory;\\n\\n#[test]\\nfn empty_and_whitespace_only_inputs_have_empty_inventories() {\\n    assert_eq!(folded_inventory(\\\"\\\"), Vec::<(char, usize)>::new());\\n    assert_eq!(\\n        folded_inventory(\\\" \\\\t\\\\n\\\\r{nbsp}{em_space}\\\"),\\n        Vec::<(char, usize)>::new()\\n    );\\n}\\n\\n#[test]\\nfn counts_ascii_case_insensitively_in_first_occurrence_order() {\\n    assert_eq!(\\n        folded_inventory(\\\"B a b A c b\\\"),\\n        vec![('b', 3), ('a', 2), ('c', 1)]\\n    );\\n}\\n\\n#[test]\\nfn full_lowercase_expansion_contributes_every_produced_scalar() {\\n    assert_eq!(\\n        folded_inventory(\\\"Bİ bA İ\\\"),\\n        vec![('b', 2), ('i', 2), ('\\\\u{307}', 2), ('a', 1)]\\n    );\\n}\\n\\n#[test]\\nfn unicode_whitespace_is_ignored_without_affecting_stable_order() {\\n    assert_eq!(\\n        folded_inventory(\\\"Ω{nbsp}A{em_space}ω\\\\tA\\\"),\\n        vec![('ω', 2), ('a', 2)]\\n    );\\n}\\n\\n#[test]\\nfn supplementary_scalars_are_counted_as_characters() {\\n    assert_eq!(\\n        folded_inventory(\\\"🦀A🦀a🚀\\\"),\\n        vec![('🦀', 2), ('a', 2), ('🚀', 1)]\\n    );\\n}\\n\\n#[test]\\nfn repeated_expansion_characters_do_not_move_existing_pairs() {\\n    assert_eq!(\\n        folded_inventory(\\\"İiİ\\\"),\\n        vec![('i', 3), ('\\\\u{307}', 2)]\\n    );\\n}\\n\"},{\"id\":\"cap-v2-string_and_unicode-rust-generation-02\",\"test_code\":\"#[path = \\\"solution.rs\\\"]\\nmod solution;\\n\\nuse solution::group_words_by_length;\\n\\nfn owned(words: &[&str]) -> Vec<String> {\\n    words.iter().map(|word| (*word).to_owned()).collect()\\n}\\n\\n#[test]\\nfn empty_and_whitespace_only_inputs_produce_no_groups() {\\n    assert_eq!(group_words_by_length(\\\"\\\"), Vec::<(usize, Vec<String>)>::new());\\n    assert_eq!(\\n        group_words_by_length(\\\" \\\\t\\\\n\\\\r{nbsp}{em_space}\\\"),\\n        Vec::<(usize, Vec<String>)>::new()\\n    );\\n}\\n\\n#[test]\\nfn groups_preserve_first_length_order_and_word_order() {\\n    assert_eq!(\\n        group_words_by_length(\\\"one a two four bb six\\\"),\\n        vec![\\n            (3, owned(&[\\\"one\\\", \\\"two\\\", \\\"six\\\"])),\\n            (1, owned(&[\\\"a\\\"])),\\n            (4, owned(&[\\\"four\\\"])),\\n            (2, owned(&[\\\"bb\\\"])),\\n        ]\\n    );\\n}\\n\\n#[test]\\nfn duplicate_words_are_retained() {\\n    assert_eq!(\\n        group_words_by_length(\\\"go go stop go stop\\\"),\\n        vec![\\n            (2, owned(&[\\\"go\\\", \\\"go\\\", \\\"go\\\"])),\\n            (4, owned(&[\\\"stop\\\", \\\"stop\\\"])),\\n        ]\\n    );\\n}\\n\\n#[test]\\nfn lengths_count_unicode_scalars_instead_of_utf8_bytes() {\\n    assert_eq!(\\n        group_words_by_length(\\\"é 🦀 é 東京 🚀🚀\\\"),\\n        vec![\\n            (1, owned(&[\\\"é\\\", \\\"🦀\\\"])),\\n            (2, owned(&[\\\"é\\\", \\\"東京\\\", \\\"🚀🚀\\\"])),\\n        ]\\n    );\\n}\\n\\n#[test]\\nfn every_unicode_whitespace_separator_splits_words() {\\n    assert_eq!(\\n        group_words_by_length(\\\"a{nbsp}{nbsp}bb{em_space}c\\\\tdd\\\\n大\\\"),\\n        vec![\\n            (1, owned(&[\\\"a\\\", \\\"c\\\", \\\"大\\\"])),\\n            (2, owned(&[\\\"bb\\\", \\\"dd\\\"])),\\n        ]\\n    );\\n}\\n\\n#[test]\\nfn leading_trailing_and_consecutive_separators_create_no_empty_words() {\\n    assert_eq!(\\n        group_words_by_length(\\\"  alpha\\\\n\\\\nβ  \\\"),\\n        vec![(5, owned(&[\\\"alpha\\\"])), (1, owned(&[\\\"β\\\"]))]\\n    );\\n}\\n\"},{\"id\":\"cap-v2-string_and_unicode-rust-repair-01\",\"test_code\":\"#[path = \\\"solution.rs\\\"]\\nmod solution;\\n\\nuse solution::compact_fragments;\\n\\nfn strings(values: &[&str]) -> Vec<String> {\\n    values.iter().map(|value| (*value).to_owned()).collect()\\n}\\n\\n#[test]\\nfn empty_input_and_empty_fragments_are_preserved() {\\n    assert_eq!(compact_fragments(&[]), Vec::<String>::new());\\n    assert_eq!(compact_fragments(&[\\\"\\\", \\\"\\\", \\\"\\\"]), strings(&[\\\"\\\", \\\"\\\", \\\"\\\"]));\\n}\\n\\n#[test]\\nfn compacts_each_maximal_whitespace_run_to_one_ascii_space() {\\n    assert_eq!(\\n        compact_fragments(&[\\\"alpha \\\\t\\\\n beta\\\", \\\"x{nbsp}{em_space}y\\\"]),\\n        strings(&[\\\"alpha beta\\\", \\\"x y\\\"])\\n    );\\n}\\n\\n#[test]\\nfn retains_leading_and_trailing_compacted_spaces() {\\n    assert_eq!(\\n        compact_fragments(&[\\\" \\\\talpha\\\\n\\\", \\\"{nbsp}\\\", \\\"beta  \\\"]),\\n        strings(&[\\\" alpha \\\", \\\" \\\", \\\"beta \\\"])\\n    );\\n}\\n\\n#[test]\\nfn whitespace_state_resets_after_fragment_ending_in_whitespace() {\\n    assert_eq!(\\n        compact_fragments(&[\\\"first   \\\", \\\"\\\\t\\\\nsecond\\\", \\\"{nbsp}third\\\"]),\\n        strings(&[\\\"first \\\", \\\" second\\\", \\\" third\\\"])\\n    );\\n}\\n\\n#[test]\\nfn empty_fragment_does_not_carry_whitespace_state_to_next_fragment() {\\n    assert_eq!(\\n        compact_fragments(&[\\\"ends \\\", \\\"\\\", \\\" starts\\\"]),\\n        strings(&[\\\"ends \\\", \\\"\\\", \\\" starts\\\"])\\n    );\\n}\\n\\n#[test]\\nfn non_whitespace_unicode_scalars_are_copied_unchanged() {\\n    assert_eq!(\\n        compact_fragments(&[\\\"é🦀東京\\\", \\\"a\\\\u{301}  ß\\\"]),\\n        strings(&[\\\"é🦀東京\\\", \\\"a\\\\u{301} ß\\\"])\\n    );\\n}\\n\\n#[test]\\nfn source_fragments_are_not_mutated() {\\n    let fragments = [\\\"a  b\\\", \\\" c\\\\t\\\"];\\n    let before = fragments;\\n\\n    let result = compact_fragments(&fragments);\\n\\n    assert_eq!(result, strings(&[\\\"a b\\\", \\\" c \\\"]));\\n    assert_eq!(fragments, before);\\n}\\n\"},{\"id\":\"cap-v2-string_and_unicode-rust-repair-02\",\"test_code\":\"#[path = \\\"solution.rs\\\"]\\nmod solution;\\n\\nuse solution::titlecase_records;\\n\\nfn strings(values: &[&str]) -> Vec<String> {\\n    values.iter().map(|value| (*value).to_owned()).collect()\\n}\\n\\n#[test]\\nfn empty_input_and_empty_records_are_preserved() {\\n    assert_eq!(titlecase_records(&[]), Vec::<String>::new());\\n    assert_eq!(titlecase_records(&[\\\"\\\", \\\"\\\"]), strings(&[\\\"\\\", \\\"\\\"]));\\n}\\n\\n#[test]\\nfn titlecases_each_whitespace_delimited_word_without_lowercasing_the_rest() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"hello world\\\", \\\"hELLO wORLD\\\"]),\\n        strings(&[\\\"Hello World\\\", \\\"HELLO WORLD\\\"])\\n    );\\n}\\n\\n#[test]\\nfn preserves_unicode_whitespace_exactly() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"alpha\\\\tbeta\\\\nγamma{nbsp}delta{em_space}echo\\\"]),\\n        strings(&[\\\"Alpha\\\\tBeta\\\\nΓamma{nbsp}Delta{em_space}Echo\\\"])\\n    );\\n}\\n\\n#[test]\\nfn uses_complete_uppercase_expansion_at_word_start() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"ßeta straße\\\", \\\"ﬃle\\\"]),\\n        strings(&[\\\"SSeta Straße\\\", \\\"FFIle\\\"])\\n    );\\n}\\n\\n#[test]\\nfn word_start_state_resets_for_every_record() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"alpha\\\", \\\"beta\\\", \\\"γamma\\\"]),\\n        strings(&[\\\"Alpha\\\", \\\"Beta\\\", \\\"Γamma\\\"])\\n    );\\n}\\n\\n#[test]\\nfn empty_record_does_not_prevent_next_record_from_starting_a_word() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"first\\\", \\\"\\\", \\\"second\\\"]),\\n        strings(&[\\\"First\\\", \\\"\\\", \\\"Second\\\"])\\n    );\\n}\\n\\n#[test]\\nfn leading_and_trailing_whitespace_are_retained() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"  alpha\\\\t\\\", \\\"\\\\nßeta{nbsp}\\\"]),\\n        strings(&[\\\"  Alpha\\\\t\\\", \\\"\\\\nSSeta{nbsp}\\\"])\\n    );\\n}\\n\\n#[test]\\nfn source_records_are_not_mutated() {\\n    let records = [\\\"alpha beta\\\", \\\"ßeta\\\"];\\n    let before = records;\\n\\n    let result = titlecase_records(&records);\\n\\n    assert_eq!(result, strings(&[\\\"Alpha Beta\\\", \\\"SSeta\\\"]));\\n    assert_eq!(records, before);\\n}\\n\"}]}"}}
